using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Net;
using System.Security.Principal;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;
using System.Windows.Forms;
using Microsoft.Win32;
namespace OpenAntiLag {
 public static class WindowsNetworkCommand {
  public static string Run(string script){script="$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.Encoding]::UTF8;"+script;string encoded=Convert.ToBase64String(Encoding.Unicode.GetBytes(script));var path=Path.Combine(Environment.SystemDirectory,@"WindowsPowerShell\v1.0\powershell.exe");var info=new ProcessStartInfo(path,"-NoLogo -NoProfile -NonInteractive -EncodedCommand "+encoded){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8};using(var process=Process.Start(info)){var output=process.StandardOutput.ReadToEndAsync();var error=process.StandardError.ReadToEndAsync();if(!process.WaitForExit(30000)){try{process.Kill();}catch(InvalidOperationException){}throw new IOException("Команда сети не ответила за 30 секунд. При записи проверьте журнал восстановления.");}string result=output.GetAwaiter().GetResult();string detail=error.GetAwaiter().GetResult();if(process.ExitCode!=0)throw new IOException("Windows отклонила сетевую операцию: "+detail);if(result.Length>4*1024*1024)throw new IOException("Слишком большой ответ Windows");return result.Trim();}}
  public static string Literal(string value){return "'"+(value??"").Replace("'","''")+"'";}
 }
 public sealed class QosNativeSnapshot {public string Name,Path,Fingerprint;public long BytesPerSecond;public int Dscp;}
 public sealed class WindowsNetworkHost:INetworkConfigurationHost {
  public static QosPolicy DecodeQos(string json){var raw=new JavaScriptSerializer().Deserialize<QosNativeSnapshot>(json);if(raw==null)return null;var result=new QosPolicy {Name=raw.Name,Path=raw.Path,BitsPerSecond=checked(raw.BytesPerSecond*8),Dscp=raw.Dscp,Fingerprint=raw.Fingerprint};NetworkValidation.Qos(result);return result;}

  static string Family(int family){if(family!=4&&family!=6)throw new ArgumentException();return family==4?"IPv4":"IPv6";}
  static int Index(string adapter,int family){Guid guid;if(!Guid.TryParse(adapter,out guid))throw new ArgumentException("Некорректный адаптер");var a=NetworkAdapters.Read().FirstOrDefault(x=>Guid.Parse(x.Id)==guid);if(a==null)throw new IOException("Адаптер отсутствует; журнал сохранён");int value=family==4?a.Index4:a.Index6;if(value<=0)throw new IOException("Семейство IPv"+family+" недоступно для адаптера");return value;}
  public static string Capability(string feature){try{string names=feature=="DNS"?"Get-DnsClientServerAddress,Set-DnsClientServerAddress":"Get-NetQosPolicy,New-NetQosPolicy,Remove-NetQosPolicy";WindowsNetworkCommand.Run("Get-Command "+names+" -ErrorAction Stop | Out-Null; 'OK'");return "Доступно. Для записи потребуется UAC; политики/драйвер могут ограничивать действие.";}catch(Exception){return "Штатный модуль "+feature+" недоступен или запрещён политикой Windows. Настройка недоступна; мониторинг работает.";}}
  public void Preflight(string feature){if(!MachineWorker.IsAdmin)throw new UnauthorizedAccessException("Сетевая запись требует отдельного UAC");string result=Capability(feature);if(!result.StartsWith("Доступно",StringComparison.Ordinal))throw new NotSupportedException(result);}
  public DnsConfig ReadDns(string adapter,int family){Guid id=Guid.Parse(adapter);Index(adapter,family);string path=@"SYSTEM\CurrentControlSet\Services\"+(family==4?"Tcpip":"Tcpip6")+@"\Parameters\Interfaces\"+id.ToString("B");using(var key=Registry.LocalMachine.OpenSubKey(path)){if(key==null)throw new IOException("Нет DNS-конфигурации адаптера IPv"+family);object raw=key.GetValue("NameServer");if(raw!=null&&!(raw is string)&&!(raw is string[]))throw new IOException("Неизвестный формат DNS override");string value=raw is string[]?String.Join(",",(string[])raw):(string)raw;return String.IsNullOrWhiteSpace(value)?new DnsConfig {Adapter=adapter,Family=family,Automatic=true}:new DnsConfig {Adapter=adapter,Family=family,Servers=NetworkInput.Servers(value,family)};}}
  public void WriteDns(DnsConfig config){NetworkValidation.Dns(config);int index=Index(config.Adapter,config.Family);string input="Get-DnsClientServerAddress -InterfaceIndex "+index+" -AddressFamily "+Family(config.Family)+" -ErrorAction Stop";string action=config.Automatic?" -ResetServerAddresses":" -ServerAddresses @("+String.Join(",",config.Servers.Select(WindowsNetworkCommand.Literal))+")";WindowsNetworkCommand.Run("$i=@("+input+");if($i.Count -ne 1){throw 'DNS instance ambiguous'};Set-DnsClientServerAddress -InputObject $i[0]"+action+" -ErrorAction Stop; 'OK'");}
  public QosPolicy ReadQos(string name){Guid id;if(!name.StartsWith("OpenAntiLag-",StringComparison.Ordinal)||!Guid.TryParse(name.Substring(12),out id))throw new ArgumentException("Имя политики не принадлежит приложению");string json=WindowsNetworkCommand.Run("$p=@(Get-NetQosPolicy -PolicyStore ActiveStore -ErrorAction Stop | Where-Object Name -eq "+WindowsNetworkCommand.Literal(name)+");if($p.Count -gt 1){throw 'QoS policy ambiguous'};if($p.Count -eq 0){'null'}else{$v=$p[0];if($v.PSObject.Properties.Name -notcontains 'ThrottleRateAction' -or $v.PSObject.Properties.Name -notcontains 'DSCPAction'){throw 'QoS properties unavailable'};[pscustomobject]@{Name=[string]$v.Name;Path=[string]$v.AppPathNameMatchCondition;BytesPerSecond=[long]$v.ThrottleRateAction;Dscp=[int]$v.DSCPAction;Fingerprint=($v | Select-Object Name,AppPathNameMatchCondition,NetworkProfile,Precedence,UserMatchCondition,IPProtocolMatchCondition,IPPortMatchCondition,IPSrcPrefixMatchCondition,IPSrcPortStartMatchCondition,IPSrcPortEndMatchCondition,IPDstPrefixMatchCondition,IPDstPortStartMatchCondition,IPDstPortEndMatchCondition,URIMatchCondition,URIRecursiveMatchCondition,NetDirectPortMatchCondition,PriorityValue8021Action,DSCPAction,MinBandwidthWeightAction,ThrottleRateAction | ConvertTo-Json -Compress)}|ConvertTo-Json -Compress}");return DecodeQos(json);}
  public void CreateQos(QosPolicy p){NetworkValidation.Qos(p);if(!File.Exists(p.Path))throw new FileNotFoundException("EXE отсутствует");WindowsNetworkCommand.Run("New-NetQosPolicy -Name "+WindowsNetworkCommand.Literal(p.Name)+" -PolicyStore ActiveStore -NetworkProfile All -AppPathNameMatchCondition "+WindowsNetworkCommand.Literal(p.Path)+(p.BitsPerSecond>0?" -ThrottleRateActionBitsPerSecond "+p.BitsPerSecond:"")+(p.Dscp>=0?" -DSCPAction "+p.Dscp:"")+" -ErrorAction Stop | Out-Null; 'OK'");}
  public void DeleteQos(string name){NetworkValidation.Qos(new QosPolicy {Name=name,Path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"validation.exe"),Dscp=0});WindowsNetworkCommand.Run("Remove-NetQosPolicy -Name "+WindowsNetworkCommand.Literal(name)+" -PolicyStore ActiveStore -Confirm:$false -ErrorAction Stop; 'OK'");}
 }
 public sealed class NetworkRequest {public DnsConfig Dns;public QosPolicy Qos;}
 public static class NetworkWorker {
  public static int Run(string action,string encoded,string sid){try{if(!MachineWorker.IsAdmin||sid!=MachineWorker.Sid)throw new UnauthorizedAccessException("Нужно подтверждение той же учётной записи");if(encoded.Length>16000)throw new InvalidDataException("Слишком большой запрос");var request=new JavaScriptSerializer().Deserialize<NetworkRequest>(Encoding.UTF8.GetString(Convert.FromBase64String(encoded)));if(request==null)throw new InvalidDataException();using(var gate=new Mutex(false,@"Global\OpenAntiLag-NetworkProfile")){bool locked=false;try{try{locked=gate.WaitOne(0);}catch(AbandonedMutexException){locked=true;}if(!locked)throw new IOException("Сетевая запись уже выполняется");var controller=new NetworkController(new WindowsNetworkHost(),new NetworkStateStore(),sid);switch(action){case "dns":controller.ApplyDns(request.Dns);break;case "qos":controller.ApplyQos(request.Qos);break;case "restore-dns":controller.Restore("DNS");break;case "restore-qos":controller.Restore("QoS");break;default:throw new ArgumentException("Операция запрещена");}}finally{if(locked)gate.ReleaseMutex();}}return 0;}catch(Exception error){MessageBox.Show(error.Message,"Open AntiLag — сеть",MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}}
 }
 public sealed class NetworkClient {
  public NetworkState State {get{return new NetworkStateStore().Load();}}
  public void Run(string action,NetworkRequest request){string encoded=Convert.ToBase64String(Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(request)));ElevatedProcess.Run(Application.ExecutablePath,"--network "+action+" "+encoded+" "+MachineWorker.Sid);}
  public void RestoreQosOnExit(){if(State.Qos.Count>0)Run("restore-qos",new NetworkRequest());}
 }
}
